// Generated by philote from page /tasks/[id]. Do not edit.
import type { Metadata } from "next";
import { notFound } from "next/navigation";
import { connection } from "next/server";
import { Suspense } from "react";

import { tasks } from "@/lib/api";
import { readTaskView } from "@/lib/reads";

import TaskView from "@/components/common/task-view";

export const metadata: Metadata = { title: "Task" };

export default function Page({ params }: PageProps<"/tasks/[id]">) {
    return (
        <main className="flex-1 px-4 py-10">
            <div className="mx-auto max-w-4xl">
                <Suspense fallback={<p className="text-muted-foreground">Loading…</p>}>
                    <Record params={params} />
                </Suspense>
            </div>
        </main>
    );
}

// Record streams in after the page's shell, so a missing record renders
// not-found.tsx with noindex, but the response status stays 200.
async function Record({ params }: Pick<PageProps<"/tasks/[id]">, "params">) {
    await connection();
    const { id } = await params;
    const result = await tasks.get(id);
    if (!result.ok) {
        notFound();
    }
    const item = await readTaskView(result.value);
    return <TaskView {...item} />;
}
